function setBitWise(idhidden, checkbox) {  var hidden = gt(idhidden);  if (checkbox.checked) hidden.value = parseInt(hidden.value) + parseInt(checkbox.value);  else hidden.value = parseInt(hidden.value) - parseInt(checkbox.value); }
function setAndConfirm(idform, tabName) {  if (!hasErrors(document.forms[0])) {  if (validateRadios(tabName)) {  if (confirm("I dati verranno confermati. Procedere?")) {  if (tabName == "<%=PSBD.TAB_AGGIUDICAZIONE%>") {  creaHidden(idform, "<%= PSBD.RESPONSABILE %>");  creaHidden(idform, "<%= PSBD.FINANZIAMENTO %>");  creaHidden(idform, "<%= PSBD.AGGIUDICATARIO %>");  creaHidden(idform, "<%= PSBD.REQUISITO %>");  creaHidden(idform, "<%= PSBD.PRESTAZIONE %>");  }  if (tabName == "<%=PSBD.TAB_ADESIONE%>") {  creaHidden(idform, "<%= PSBD.RESPONSABILE %>");  creaHidden(idform, "<%= PSBD.FINANZIAMENTO %>");  creaHidden(idform, "<%= PSBD.AGGIUDICATARIO %>");  } else if (tabName == "<%=ParametriServletInizioLavori.TAB_INIZIO_LAVORI%>") {  creaHidden(idform, "<%= ParametriServletInizioLavori.POSIZIONE_AGGIUDICATARIO %>");  creaHidden(idform, "<%= PSBD.RESPONSABILE %>");  } else if (tabName == "<%=PSBD.TAB_SOTTOSOGLIA%>") {  creaHidden(idform, "<%= PSBD.RESPONSABILE %>");  creaHidden(idform, "<%= PSBD.AGGIUDICATARIO %>");  } else if (tabName == "<%=PSBD.TAB_ESCLUSI%>") {  creaHidden(idform, "<%= PSBD.RESPONSABILE %>");  creaHidden(idform, "<%= PSBD.AGGIUDICATARIO %>");  }  document.forms[0].elements['<%=PSBD.TAB%>'].value = tabName;  document.forms[0].elements['<%=PSBD.ACTION_TYPE%>'].value = "<%=PSBD.ACTION_CONFERMA%>";  document.forms[0].submit();  }  }  } }
function validateRadios(tabname) {  if ("<%= PSBD.TAB_INFO_COMUNI%>" == tabname) {  return (checkRadio('<%= ParametriServlet.S_FIELD_NAME_SITO_MIN_INF_TRASP %>', '<%= ParametriServlet.N_FIELD_NAME_SITO_MIN_INF_TRASP %>') && checkRadio('<%= ParametriServlet.S_FIELD_NAME_SITO_OSSERVATORIO_CP %>', '<%= ParametriServlet.N_FIELD_NAME_SITO_OSSERVATORIO_CP %>') && checkRadio('<%= ParametriServlet.S_FIELD_NAME_PROFILO_COMMITTENTE %>', '<%= ParametriServlet.N_FIELD_NAME_PROFILO_COMMITTENTE %>'));  } else if ("<%= PSBD.TAB_AGGIUDICAZIONE%>" == tabname) {  var flagEnte = '${schedaA.infoComuni.flagEnteSpeciale}';  return (checkRadio('<%= PSBD.S_FIELD_NAME_ASTA_ELETTRONICA %>', '<%= PSBD.N_FIELD_NAME_ASTA_ELETTRONICA %>') && ((flagEnte != 'S') || checkRadio('<%= PSBD.S_FIELD_NAME_CRITERI_SELEZIONE_STABILITI_SA %>', '<%= PSBD.N_FIELD_NAME_CRITERI_SELEZIONE_STABILITI_SA %>')) && ((flagEnte != 'S') || checkRadio('<%= PSBD.S_FIELD_NAME_SISTEMA_QUALIFICAZIONE %>', '<%= PSBD.N_FIELD_NAME_SISTEMA_QUALIFICAZIONE %>')) && checkRadio('check2Y', 'check2N') && checkRadio('check3Y', 'check3N') && checkRadio('check4Y', 'check4N') && checkRadio('affidatarioY', 'affidatarioN'));  } else if ("<%= PSBD.TAB_ADESIONE%>" == tabname) {  return checkRadio('affidatarioY', 'affidatarioN');  } else if ("<%= ParametriServletInizioLavori.TAB_INIZIO_LAVORI%>" == tabname) {  return (checkRadio('<%= ParametriServlet.S_FIELD_NAME_SITO_MIN_INF_TRASP %>', '<%= ParametriServlet.N_FIELD_NAME_SITO_MIN_INF_TRASP %>') && checkRadio('<%= ParametriServlet.S_FIELD_NAME_SITO_OSSERVATORIO_CP %>', '<%= ParametriServlet.N_FIELD_NAME_SITO_OSSERVATORIO_CP %>') && checkRadio('<%= ParametriServletInizioLavori.SI_FLAG_RISERVA %>', '<%= ParametriServletInizioLavori.NO_FLAG_RISERVA %>') && checkRadio('<%= ParametriServlet.S_FIELD_NAME_PROFILO_COMMITTENTE %>', '<%= ParametriServlet.N_FIELD_NAME_PROFILO_COMMITTENTE %>'));  } else if ("<%= PSBD.TAB_SOTTOSOGLIA%>" == tabname) {  return checkRadio('<%= PSBD.S_FIELD_NAME_ASTA_ELETTRONICA %>', '<%= PSBD.N_FIELD_NAME_ASTA_ELETTRONICA %>');  } else if ("<%= PSBD.TAB_ESCLUSI%>" == tabname) {  return checkRadio('<%= PSBD.S_FIELD_NAME_ASTA_ELETTRONICA %>', '<%= PSBD.N_FIELD_NAME_ASTA_ELETTRONICA %>');  }  return true; }
function validateRadio(prefix) {  if (prefix == "<%= PSBD.RESPONSABILE %>" || prefix == "<%= PSBD.PRESTAZIONE %>" || prefix == "<%= PSBD.AGGIUDICATARIO %>" || prefix == "<%= PSBD.FINANZIAMENTO %>" || prefix == "CUP" ) return true;  if (prefix == "<%= PSBD.CONTENZIOSO %>") return checkRadio('<%= PSBD.S_FIELD_NAME_CONTENZIOSO_GARA %>', '<%= PSBD.N_FIELD_NAME_CONTENZIOSO_GARA %>');  else if (prefix == "<%= PSBD.REQUISITO %>" || prefix == "<%= PSBD.DITTA_AUSILIARIA %>" || prefix == "<%= PSBD.DITTA_RAGGRUPPAMENTO %>") return (true);  else return false; }
function checkRadio(idYes, idNo) {  var elemYes = gt(idYes);  var elemNo = gt(idNo);  if ((!elemYes.checked) && (!elemNo.checked)) {  alert("Selezionare almeno un opzione per tutti i campi Si/No");  return false;  }  return true; }
