function checkElement(prefix, parameters) {  var idtable = "idTabella" + prefix;  var table = gt(idtable);  if (table != null) {  var numrows = table.rows.length;  if (numrows == 0) return true;  var esiste = true;  for (var i = 0; i < numrows; i++) {  var uguale = false;  for (var j = 0; j < parameters.length; j++) {  var idElem = "row" + prefix + i + parameters[j];  var element = gt(idElem);  var inmodifica = gt("inModifica" + prefix);  if (element != null && (inmodifica == null || inmodifica.value != ("row" + prefix + i))) {  var value = "";  if (element.childNodes[0] != null) value = element.childNodes[0].data;  var field = gt(parameters[j]);  var fieldvalue;  if (prefix == "<%= PSBD.DITTA_AUSILIARIA %>") {  value = element.innerHTML;  }  if ("<%= PSBD.FIELD_NAME_COD_FISC_POSIZIONI %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_COD_FISC_POSIZIONI %>");  fieldvalue = getSelectValue(field, false);  var id = "hiddenrow" + prefix + i + "<%= PSBD.FIELD_NAME_COD_FISC_POSIZIONI %>";  field = gt(id).value;  value = field;  } else if ("<%= PSBD.FIELD_NAME_DESCRIZIONE_RUOLO_RESPONSABILE %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_ID_RUOLO_RESPONSABILE %>");  fieldvalue = getSelectValue(field, true);  } else if ("<%= PSBD.FIELD_NAME_PRESTAZIONE_DESCRIZIONE_RUOLO %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_PRESTAZIONE_ID_RUOLO %>");  fieldvalue = getSelectValue(field, true);  } else if ("<%= PSBD.FIELD_NAME_DES_FINANZIAMENTO %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_TIPO_FINANZIAMENTO %>");  fieldvalue = getSelectValue(field, true);  } else if ("<%= PSBD.FIELD_NAME_AGG_ID_RUOLO %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_AGG_RUOLO %>");  fieldvalue = getSelectValue(field, true);  } else if ("<%= PSBD.FIELD_NAME_AGG_ID_TIPO_AGG %>" == parameters[j]) {  fieldvalue = getSelectValue(field, false);  } else if ("<%= PSBD.FIELD_NAME_ID_CATEGORIA %>" == parameters[j]) {  field = gt("<%= PSBD.FIELD_NAME_ID_CATEGORIA %>");  fieldvalue = getSelectValue(field, true);  } else {  fieldvalue = field.value;  }  if (value != fieldvalue) {  uguale = false;  break;  } else {  uguale = true;  }  } else {  j++;  }  }  if (uguale == true) {  return false;  }  }  return true;  } }
