function modifyRow(idrow, args, argshidden, prefix) {  if (prefix == "<%= ParametriServletInizioLavori.POSIZIONE_AGGIUDICATARIO %>" && gt("<%= PSBD.FIELD_NAME_COD_FISC_POSIZIONI%>").selectedIndex <= 0) {  alert("E' necessario scegliere un soggetto per poter proseguire.");  } else if (prefix == "<%= PSBD.AGGIUDICATARIO %>" && gt("<%= PSBD.FIELD_NAME_PERC_RIBASSO_AGGIUDICATARIO %>").value!='' && gt("<%= PSBD.FIELD_NAME_PERC_AUMENTO_AGGIUDICATARIO %>").value!=''){ alert("Sono stati indicati sia Ribasso aggiudicazione che Offerta in aumento."); }else if (prefix == "<%= PSBD.AGGIUDICATARIO %>" && gt("<%= PSBD.FIELD_NAME_AGG_ID_TIPO_AGG%>").selectedIndex == 0){ alert("SIMOG_VALIDAZIONE_104 - Tipologia del soggetto aggiudicatario/affidatario: selezionare un valore tra quelli previsti."); } else {  if (checkBeforeAdd(prefix)) {  var row = gt(idrow);  var id = row.getAttribute("id");  fillRow(id, args, argshidden, prefix);  appendHidden(row, id, prefix, getArray(prefix, false), false);  setModificato(prefix);  hideSezioneAggiungi(args, argshidden, prefix);  }  } }
function getSelectValue(elem, flagValue) {  var ret = "";  if (elem.selectedIndex >= 0) {  var sele = elem.options[elem.selectedIndex];  ret = sele.text;  if (flagValue == true) {  ret = sele.value;  }  }  return ret; }
function cercaIndex(array, index, value) {  if (index == array.length) return - 1;  if (array[index].value == value) return index;  return cercaIndex(array, (index + 1), value); }
function getTipoAggiudicatario(idElement) {  var textElement = "";  if (idElement == 1) {  textElement = "<%= PSBD.FIELD_NAME_AGG_ATI%>";  } else if (idElement == 2) {  textElement = "<%= PSBD.FIELD_NAME_AGG_CONSORZIO%>";  } else if (idElement == 3) {  textElement = "<%= PSBD.FIELD_NAME_AGG_IMPRESA_SINGOLA%>";  } else if (idElement == 4) {  textElement = "<%= PSBD.FIELD_NAME_AGG_GEIE%>";  } else if (idElement == 5) {  textElement = "<%= PSBD.FIELD_NAME_ASSOCIAZIONE_CATEGORIA%>";  } else {  textElement = "";  }  return textElement; }
